#include <iostream>

template<typename T>
T my_min(T a, T b) {
    if (a < b) {
        return a;
    }
    return b;
}

template<typename T>
T my_max(T a, T b) {
    if (a > b) {
        return a;
    }
    return b;
}

int main() {
    std::cout << my_min(8, 3) << '\n';
    std::cout << my_max(8, 3) << '\n';
    std::cout << my_min(2.5, 4.0) << '\n';
    std::cout << my_max(2.5, 4.0) << '\n';
}
